"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/** Same CDN pattern as `/tools/flags` (jsDelivr → SonoJS-flags). */
export const DEFAULT_FLAG_CDN_BASE =
  "https://cdn.jsdelivr.net/gh/SonoJS/SonoJS-flags@main/flags"

export function flagSrc(code: string, base: string = DEFAULT_FLAG_CDN_BASE) {
  const iso = code.trim().slice(0, 2).toLowerCase()
  return `${base.replace(/\/$/, "")}/${iso}.svg`
}

function isoToFlagEmoji(code: string) {
  const iso = code.trim().toUpperCase().slice(0, 2)
  if (!/^[A-Z]{2}$/.test(iso)) return ""
  return String.fromCodePoint(
    ...[...iso].map((char) => 127397 + char.charCodeAt(0))
  )
}

export function CountryFlag({
  code,
  flagCdnBase = DEFAULT_FLAG_CDN_BASE,
  emojiFallback,
  className,
  size = "md",
}: {
  code: string
  flagCdnBase?: string
  emojiFallback?: string
  className?: string
  size?: "sm" | "md"
}) {
  const sourceKey = `${flagCdnBase}|${code}`
  const [failedKey, setFailedKey] = React.useState<string | null>(null)
  const failed = failedKey === sourceKey

  const box = "h-4 w-6 shrink-0 rounded-[2px]"

  if (failed) {
    const emoji = emojiFallback?.trim() || isoToFlagEmoji(code)
    if (emoji) {
      return (
        <span
          className={cn(
            size === "sm" ? "text-sm" : "text-base",
            "leading-none",
            className
          )}
          aria-hidden
        >
          {emoji}
        </span>
      )
    }
    return (
      <span
        className={cn(
          "flex items-center justify-center bg-muted text-[8px] font-semibold leading-none text-muted-foreground",
          box,
          className
        )}
        aria-hidden
      >
        {code.slice(0, 2).toUpperCase()}
      </span>
    )
  }

  return (
    <img
      src={flagSrc(code, flagCdnBase)}
      alt=""
      width={24}
      height={16}
      loading="lazy"
      decoding="async"
      aria-hidden
      className={cn("object-cover object-center", box, className)}
      onError={() => setFailedKey(sourceKey)}
    />
  )
}

/** jsDelivr npm data shards (no pinned version in URL). */
export const DEFAULT_GEO_DATA_BASE_URL =
  "https://cdn.jsdelivr.net/npm/@sonojs/geo/data/"

let configuredBase: string | null = null

export function resolveDataBaseUrl(override?: string) {
  const base = (
    override ??
    configuredBase ??
    DEFAULT_GEO_DATA_BASE_URL
  ).replace(/\/?$/, "/")
  configuredBase = base
  return base
}

export function ensureGeoConfigured(dataBaseUrl?: string) {
  return resolveDataBaseUrl(dataBaseUrl)
}

export function getConfiguredGeoBase() {
  return configuredBase ?? DEFAULT_GEO_DATA_BASE_URL
}

import type { City, Country, State } from "@sonojs/geo"

import {
  ensureGeoConfigured,
  getConfiguredGeoBase,
  resolveDataBaseUrl,
} from "./geo-config"
import { matchesCountryFields, normalizeQuery } from "./geo-search"

const jsonCache = new Map<string, Promise<unknown>>()

let countriesBase: string | null = null
let countriesPromise: Promise<Country[]> | null = null

const statesByIso = new Map<string, Promise<State[]>>()
const citiesByIso = new Map<string, Promise<City[]>>()

export function resetGeoDataModuleCache() {
  countriesBase = null
  countriesPromise = null
  statesByIso.clear()
  citiesByIso.clear()
  jsonCache.clear()
}

function bindBase(dataBaseUrl?: string) {
  const base = dataBaseUrl
    ? resolveDataBaseUrl(dataBaseUrl)
    : ensureGeoConfigured()
  if (countriesBase && countriesBase !== base) {
    resetGeoDataModuleCache()
    countriesBase = base
  } else if (!countriesBase) {
    countriesBase = base
  }
  return base
}

async function loadJson<T>(base: string, relative: string): Promise<T> {
  const url = `${base}${relative.replace(/^\//, "")}`
  let pending = jsonCache.get(url) as Promise<T> | undefined
  if (!pending) {
    pending = (async () => {
      const res = await fetch(url)
      if (!res.ok) {
        throw new Error(`HTTP ${res.status} for ${url}`)
      }
      return (await res.json()) as T
    })()
    jsonCache.set(url, pending)
  }
  return pending
}

function stateShardPath(iso2: string) {
  return `states/${iso2.trim().toLowerCase()}.json`
}

function cityShardPath(iso2: string) {
  return `cities/${iso2.trim().toLowerCase()}.json`
}

export function reconfigureGeo(dataBaseUrl: string) {
  resetGeoDataModuleCache()
  return resolveDataBaseUrl(dataBaseUrl)
}

export async function fetchCountries(dataBaseUrl?: string) {
  const base = bindBase(dataBaseUrl)
  if (!countriesPromise) {
    countriesPromise = loadJson<Country[]>(base, "countries.json")
  }
  return countriesPromise
}

export async function fetchCountryByIso2(iso2: string, dataBaseUrl?: string) {
  bindBase(dataBaseUrl)
  const countries = await fetchCountries()
  const code = iso2.trim().toUpperCase()
  return countries.find((c) => c.iso2.toUpperCase() === code)
}

export function filterCountries(
  countries: Country[],
  query: string
): Country[] {
  const needle = query.trim().toLowerCase()
  if (!needle) return countries
  return countries.filter(
    (c) =>
      c.name.toLowerCase().includes(needle) ||
      c.iso2.toLowerCase().includes(needle) ||
      (c.native?.toLowerCase().includes(needle) ?? false)
  )
}

export async function fetchStatesByCountry(
  countryIso2: string,
  dataBaseUrl?: string
): Promise<State[]> {
  const iso = countryIso2?.trim().toUpperCase()
  if (!iso) return []
  const base = bindBase(dataBaseUrl)
  let pending = statesByIso.get(iso)
  if (!pending) {
    pending = loadJson<State[]>(base, stateShardPath(iso)).catch(() => [])
    statesByIso.set(iso, pending)
  }
  return pending
}

/** Warm the light state shard after country selection. */
export function prefetchStatesByCountry(
  countryIso2: string | null | undefined,
  dataBaseUrl?: string
) {
  const iso = countryIso2?.trim().toUpperCase()
  if (!iso) return
  void fetchStatesByCountry(iso, dataBaseUrl).catch(() => {})
}

export async function fetchStateById(
  stateId: number,
  countryIso2: string,
  dataBaseUrl?: string
): Promise<State | undefined> {
  if (!Number.isFinite(stateId) || stateId <= 0) return undefined
  const states = await fetchStatesByCountry(countryIso2, dataBaseUrl)
  return states.find((s) => s.id === stateId)
}

export function filterStates(states: State[], query: string): State[] {
  const q = normalizeQuery(query)
  if (!q) return states
  return states.filter((s) =>
    matchesCountryFields([s.name, s.native, s.iso2, s.iso3166_2], q)
  )
}

export async function fetchSearchStates(
  query: string,
  countryIso2: string,
  dataBaseUrl?: string,
  limit = 50
) {
  const states = await fetchStatesByCountry(countryIso2, dataBaseUrl)
  const sorted = [...states].sort((a, b) =>
    a.name.localeCompare(b.name, undefined, { sensitivity: "base" })
  )
  const filtered = filterStates(sorted, query)
  return filtered.slice(0, limit)
}

export async function fetchCitiesByCountry(
  countryIso2: string,
  dataBaseUrl?: string
): Promise<City[]> {
  const iso = countryIso2?.trim().toUpperCase()
  if (!iso) return []
  const base = bindBase(dataBaseUrl)
  let pending = citiesByIso.get(iso)
  if (!pending) {
    pending = loadJson<City[]>(base, cityShardPath(iso))
    citiesByIso.set(iso, pending)
  }
  return pending
}

/** Warm the city shard (prefer after state select when using includeState). */
export function prefetchCitiesByCountry(
  countryIso2: string | null | undefined,
  dataBaseUrl?: string
) {
  const iso = countryIso2?.trim().toUpperCase()
  if (!iso) return
  void fetchCitiesByCountry(iso, dataBaseUrl).catch(() => {})
}

export async function fetchCitiesByState(
  countryIso2: string,
  stateId: number,
  dataBaseUrl?: string
): Promise<City[]> {
  if (!Number.isFinite(stateId) || stateId <= 0) return []
  const cities = await fetchCitiesByCountry(countryIso2, dataBaseUrl)
  return cities.filter((c) => c.state_id === stateId)
}

export async function fetchCityByIdInCountry(
  cityId: number,
  countryIso2: string,
  dataBaseUrl?: string
): Promise<City | undefined> {
  if (!Number.isFinite(cityId) || cityId <= 0) return undefined
  const cities = await fetchCitiesByCountry(countryIso2, dataBaseUrl)
  return cities.find((c) => c.id === cityId)
}

export async function fetchSearchCities(
  query: string,
  countryIso2: string,
  dataBaseUrl?: string,
  limit = 25,
  stateId?: number | null
) {
  const q = normalizeQuery(query)
  const iso = countryIso2?.trim().toUpperCase()
  if (!iso) return []

  const cities =
    stateId != null && Number.isFinite(stateId) && stateId > 0
      ? await fetchCitiesByState(iso, stateId, dataBaseUrl)
      : await fetchCitiesByCountry(iso, dataBaseUrl)

  if (!q) {
    const sorted = [...cities].sort((a, b) =>
      a.name.localeCompare(b.name, undefined, { sensitivity: "base" })
    )
    return sorted.slice(0, limit)
  }

  const matched: City[] = []
  for (const city of cities) {
    if (matchesCountryFields([city.name], q)) {
      matched.push(city)
      if (matched.length >= limit) break
    }
  }
  return matched
}

export function activeGeoDataBaseUrl() {
  return getConfiguredGeoBase()
}

/** Country name search (aligned with `@sonojs/geo` search semantics). */

const graphemeSegmenter = new Intl.Segmenter(undefined, {
  granularity: "grapheme",
})

const defaultCollator = new Intl.Collator(undefined, {
  usage: "search",
  sensitivity: "base",
  ignorePunctuation: true,
})

export function normalizeQuery(query: string) {
  return query.normalize("NFC").trim()
}

function graphemes(text: string) {
  return [...graphemeSegmenter.segment(text)].map((s) => s.segment)
}

function stripPunctuationGraphemes(text: string) {
  return graphemes(text)
    .filter((g) => !/[\p{P}\p{S}]/u.test(g))
    .join("")
}

function collatorContains(haystack: string, needle: string) {
  const n = normalizeQuery(needle)
  if (!n) return false
  const h = haystack.normalize("NFC")
  const hCmp = stripPunctuationGraphemes(h)
  const nCmp = stripPunctuationGraphemes(n)
  const hG = graphemes(hCmp)
  const nG = graphemes(nCmp)
  const win = nG.length
  if (win === 0 || hG.length < win) return false
  for (let i = 0; i <= hG.length - win; i++) {
    const slice = hG.slice(i, i + win).join("")
    if (defaultCollator.compare(slice, nCmp) === 0) return true
  }
  return false
}

export function matchesCountryFields(
  fields: (string | null | undefined)[],
  query: string
) {
  const q = normalizeQuery(query)
  if (!q) return false
  for (const f of fields) {
    if (f != null && f !== "" && collatorContains(f, q)) return true
  }
  return false
}

"use client"

import * as React from "react"
import type { Country } from "@sonojs/geo"

import { cn } from "@/lib/utils"

import { CountryFlag, DEFAULT_FLAG_CDN_BASE } from "./country-flag"
import {
  fetchCountries,
  fetchCountryByIso2,
  filterCountries,
} from "./geo-data"
import { PickerPopoverList } from "./picker-popover-list"

export type CountrySearchSelectProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange"
> & {
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (iso2: string | null, country?: Country | null) => void
  disabled?: boolean
  placeholder?: string
  emptyMessage?: string
  geoDataBaseUrl?: string
  flagCdnBase?: string
  showFlags?: boolean
  className?: string
  id?: string
}

function CountrySearchSelect({
  value: valueProp,
  defaultValue = null,
  onValueChange,
  disabled = false,
  placeholder = "Choose country",
  emptyMessage = "No countries found.",
  geoDataBaseUrl,
  flagCdnBase = DEFAULT_FLAG_CDN_BASE,
  showFlags = true,
  className,
  id,
  ...props
}: CountrySearchSelectProps) {
  const [open, setOpen] = React.useState(false)
  const [listQuery, setListQuery] = React.useState("")
  const [countries, setCountries] = React.useState<Country[]>([])
  const [status, setStatus] = React.useState<
    "idle" | "loading" | "ready" | "error"
  >("idle")
  const [uncontrolled, setUncontrolled] = React.useState<string | null>(
    defaultValue
  )
  const [selectedCountry, setSelectedCountry] = React.useState<Country | null>(
    null
  )

  const isControlled = valueProp !== undefined
  const selectedIso = isControlled ? valueProp : uncontrolled

  const setSelectedIso = React.useCallback(
    (iso: string | null, country?: Country | null) => {
      if (!isControlled) setUncontrolled(iso)
      setSelectedCountry(country ?? null)
      onValueChange?.(iso, country ?? null)
    },
    [isControlled, onValueChange]
  )

  React.useEffect(() => {
    if (!selectedIso) {
      setSelectedCountry(null)
      return
    }
    let cancelled = false
    void (async () => {
      const country = await fetchCountryByIso2(selectedIso, geoDataBaseUrl)
      if (!cancelled) setSelectedCountry(country ?? null)
    })()
    return () => {
      cancelled = true
    }
  }, [geoDataBaseUrl, selectedIso])

  React.useEffect(() => {
    if (!open || status === "ready") return
    let cancelled = false
    setStatus("loading")
    void fetchCountries(geoDataBaseUrl)
      .then((list) => {
        if (cancelled) return
        setCountries(
          [...list].sort((a, b) =>
            a.name.localeCompare(b.name, undefined, { sensitivity: "base" })
          )
        )
        setStatus("ready")
      })
      .catch(() => {
        if (cancelled) return
        setCountries([])
        setStatus("error")
      })
    return () => {
      cancelled = true
    }
  }, [geoDataBaseUrl, open, status])

  const filtered = React.useMemo(
    () => filterCountries(countries, listQuery),
    [countries, listQuery]
  )

  const visible = React.useMemo(
    () => filtered.slice(0, listQuery.trim() ? 50 : 80),
    [filtered, listQuery]
  )

  const triggerLabel = selectedCountry ? (
    <span className="flex items-center gap-2">
      {showFlags ? (
        <CountryFlag
          code={selectedCountry.iso2}
          flagCdnBase={flagCdnBase}
          emojiFallback={selectedCountry.emoji}
        />
      ) : null}
      <span className="truncate">{selectedCountry.name}</span>
    </span>
  ) : (
    <span className="text-muted-foreground">{placeholder}</span>
  )

  return (
    <div
      id={id}
      data-slot="country-search-select"
      className={cn("w-full", className)}
      {...props}
    >
      <PickerPopoverList
        disabled={disabled}
        open={open}
        onOpenChange={setOpen}
        listQuery={listQuery}
        onListQueryChange={setListQuery}
        searchPlaceholder="Search country…"
        triggerLabel={triggerLabel}
        triggerAriaLabel="Country"
        emptyMessage={
          status === "error" ? "Could not load countries." : emptyMessage
        }
        loading={open && status === "loading"}
        items={visible}
        getKey={(c) => c.iso2}
        isSelected={(c) => c.iso2 === selectedIso}
        onPick={(country) => setSelectedIso(country.iso2, country)}
        renderItem={(country) => (
          <>
            {showFlags ? (
              <CountryFlag
                code={country.iso2}
                flagCdnBase={flagCdnBase}
                emojiFallback={country.emoji}
              />
            ) : null}
            <span className="min-w-0 flex-1 truncate text-start">
              {country.name}
            </span>
            <span className="text-muted-foreground tabular-nums">
              {country.iso2}
            </span>
          </>
        )}
      />
    </div>
  )
}

export { CountrySearchSelect }

"use client"

import * as React from "react"
import type { State } from "@sonojs/geo"

import { cn } from "@/lib/utils"

import {
  fetchSearchStates,
  fetchStateById,
  prefetchStatesByCountry,
} from "./geo-data"
import { PickerPopoverList } from "./picker-popover-list"

export type StateSearchSelectProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange"
> & {
  countryIso?: string | null
  stateId?: number | null
  defaultStateId?: number | null
  onStateChange?: (stateId: number | null, state?: State | null) => void
  disabled?: boolean
  placeholder?: string
  emptyMessage?: string
  geoDataBaseUrl?: string
  className?: string
  id?: string
}

function StateSearchSelect({
  countryIso,
  stateId: stateIdProp,
  defaultStateId = null,
  onStateChange,
  disabled = false,
  placeholder = "Choose state / province",
  emptyMessage = "No states found.",
  geoDataBaseUrl,
  className,
  id,
  ...props
}: StateSearchSelectProps) {
  const [open, setOpen] = React.useState(false)
  const [listQuery, setListQuery] = React.useState("")
  const [results, setResults] = React.useState<State[]>([])
  const [status, setStatus] = React.useState<
    "idle" | "loading" | "ready" | "error"
  >("idle")
  const [uncontrolled, setUncontrolled] = React.useState<number | null>(
    defaultStateId
  )
  const [selectedState, setSelectedState] = React.useState<State | null>(null)
  const requestIdRef = React.useRef(0)

  const isControlled = stateIdProp !== undefined
  const selectedId = isControlled ? stateIdProp : uncontrolled
  const locked = disabled || !countryIso

  const setSelectedStateId = React.useCallback(
    (id: number | null, state?: State | null) => {
      if (!isControlled) setUncontrolled(id)
      setSelectedState(state ?? null)
      onStateChange?.(id, state ?? null)
    },
    [isControlled, onStateChange]
  )

  React.useEffect(() => {
    setListQuery("")
    setResults([])
    setStatus("idle")
    setOpen(false)
    if (!countryIso) {
      setSelectedState(null)
      if (!isControlled) setUncontrolled(null)
    }
  }, [countryIso, isControlled])

  React.useEffect(() => {
    prefetchStatesByCountry(countryIso, geoDataBaseUrl)
  }, [countryIso, geoDataBaseUrl])

  React.useEffect(() => {
    if (!countryIso || selectedId == null) return
    if (selectedState?.id === selectedId) return
    let cancelled = false
    void fetchStateById(selectedId, countryIso, geoDataBaseUrl).then(
      (state) => {
        if (!cancelled && state) setSelectedState(state)
      }
    )
    return () => {
      cancelled = true
    }
  }, [countryIso, geoDataBaseUrl, selectedId, selectedState?.id])

  React.useEffect(() => {
    if (!open || locked || !countryIso) return

    const requestId = ++requestIdRef.current
    const timer = window.setTimeout(() => {
      void (async () => {
        try {
          setStatus("loading")
          const hits = await fetchSearchStates(
            listQuery,
            countryIso,
            geoDataBaseUrl,
            80
          )
          if (requestId !== requestIdRef.current) return
          setResults(hits)
          setStatus("ready")
        } catch {
          if (requestId !== requestIdRef.current) return
          setResults([])
          setStatus("error")
        }
      })()
    }, listQuery.trim() ? 200 : 0)

    return () => window.clearTimeout(timer)
  }, [countryIso, geoDataBaseUrl, listQuery, locked, open])

  const triggerLabel = selectedState ? (
    <span className="truncate">{selectedState.name}</span>
  ) : (
    <span className="text-muted-foreground">
      {countryIso ? placeholder : "Select a country first"}
    </span>
  )

  return (
    <div
      id={id}
      data-slot="state-search-select"
      className={cn("w-full", className)}
      {...props}
    >
      <PickerPopoverList
        disabled={locked}
        open={open}
        onOpenChange={setOpen}
        listQuery={listQuery}
        onListQueryChange={setListQuery}
        searchPlaceholder="Search state / province…"
        triggerLabel={triggerLabel}
        triggerAriaLabel="State or province"
        emptyMessage={
          status === "error" ? "Could not load states." : emptyMessage
        }
        loading={open && status === "loading"}
        items={results}
        getKey={(s) => String(s.id)}
        isSelected={(s) => s.id === selectedId}
        onPick={(state) => setSelectedStateId(state.id, state)}
        renderItem={(state) => (
          <>
            <span className="min-w-0 flex-1 truncate text-start">
              {state.name}
            </span>
            {state.iso2 ? (
              <span className="text-muted-foreground tabular-nums">
                {state.iso2}
              </span>
            ) : null}
          </>
        )}
      />
    </div>
  )
}

export { StateSearchSelect }

"use client"

import * as React from "react"
import type { City } from "@sonojs/geo"

import { cn } from "@/lib/utils"

import {
  fetchCityByIdInCountry,
  fetchSearchCities,
  prefetchCitiesByCountry,
} from "./geo-data"
import { PickerPopoverList } from "./picker-popover-list"

export type CitySearchSelectProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange"
> & {
  countryIso?: string | null
  /** When set, city list is filtered to this state (lighter search set). */
  stateId?: number | null
  /** Require a state before the city field unlocks. */
  requireState?: boolean
  cityId?: number | null
  defaultCityId?: number | null
  onCityChange?: (cityId: number | null, city?: City | null) => void
  disabled?: boolean
  placeholder?: string
  emptyMessage?: string
  geoDataBaseUrl?: string
  className?: string
  id?: string
}

function CitySearchSelect({
  countryIso,
  stateId = null,
  requireState = false,
  cityId: cityIdProp,
  defaultCityId = null,
  onCityChange,
  disabled = false,
  placeholder = "Choose city",
  emptyMessage = "No cities found.",
  geoDataBaseUrl,
  className,
  id,
  ...props
}: CitySearchSelectProps) {
  const [open, setOpen] = React.useState(false)
  const [listQuery, setListQuery] = React.useState("")
  const [results, setResults] = React.useState<City[]>([])
  const [status, setStatus] = React.useState<
    "idle" | "loading" | "ready" | "error"
  >("idle")
  const [uncontrolled, setUncontrolled] = React.useState<number | null>(
    defaultCityId
  )
  const [selectedCity, setSelectedCity] = React.useState<City | null>(null)
  const requestIdRef = React.useRef(0)

  const isControlled = cityIdProp !== undefined
  const selectedId = isControlled ? cityIdProp : uncontrolled
  const needsState = requireState && stateId == null
  const locked = disabled || !countryIso || needsState

  const setSelectedCityId = React.useCallback(
    (id: number | null, city?: City | null) => {
      if (!isControlled) setUncontrolled(id)
      setSelectedCity(city ?? null)
      onCityChange?.(id, city ?? null)
    },
    [isControlled, onCityChange]
  )

  React.useEffect(() => {
    setListQuery("")
    setResults([])
    setStatus("idle")
    setOpen(false)
    setSelectedCity(null)
    if (!isControlled) setUncontrolled(null)
  }, [countryIso, isControlled, stateId])

  React.useEffect(() => {
    if (!countryIso) return
    if (requireState && stateId == null) return
    prefetchCitiesByCountry(countryIso, geoDataBaseUrl)
  }, [countryIso, geoDataBaseUrl, requireState, stateId])

  React.useEffect(() => {
    if (!countryIso || selectedId == null) return
    if (selectedCity?.id === selectedId) return
    let cancelled = false
    void fetchCityByIdInCountry(selectedId, countryIso, geoDataBaseUrl).then(
      (city) => {
        if (!cancelled && city) setSelectedCity(city)
      }
    )
    return () => {
      cancelled = true
    }
  }, [countryIso, geoDataBaseUrl, selectedCity?.id, selectedId])

  React.useEffect(() => {
    if (!open || locked || !countryIso) return
    if (requireState && stateId == null) return

    const requestId = ++requestIdRef.current
    const timer = window.setTimeout(() => {
      void (async () => {
        try {
          setStatus("loading")
          const hits = await fetchSearchCities(
            listQuery,
            countryIso,
            geoDataBaseUrl,
            50,
            requireState ? stateId : null
          )
          if (requestId !== requestIdRef.current) return
          setResults(hits)
          setStatus("ready")
        } catch {
          if (requestId !== requestIdRef.current) return
          setResults([])
          setStatus("error")
        }
      })()
    }, listQuery.trim() ? 200 : 0)

    return () => window.clearTimeout(timer)
  }, [
    countryIso,
    geoDataBaseUrl,
    listQuery,
    locked,
    open,
    requireState,
    stateId,
  ])

  const triggerLabel = selectedCity ? (
    <span className="truncate">{selectedCity.name}</span>
  ) : (
    <span className="text-muted-foreground">
      {!countryIso
        ? "Select a country first"
        : needsState
          ? "Select a state first"
          : placeholder}
    </span>
  )

  return (
    <div
      id={id}
      data-slot="city-search-select"
      className={cn("w-full", className)}
      {...props}
    >
      <PickerPopoverList
        disabled={locked}
        open={open}
        onOpenChange={setOpen}
        listQuery={listQuery}
        onListQueryChange={setListQuery}
        searchPlaceholder="Search city…"
        triggerLabel={triggerLabel}
        triggerAriaLabel="City"
        emptyMessage={
          status === "error" ? "Could not load cities." : emptyMessage
        }
        loading={open && status === "loading"}
        items={results}
        getKey={(c) => String(c.id)}
        isSelected={(c) => c.id === selectedId}
        onPick={(city) => setSelectedCityId(city.id, city)}
        renderItem={(city) => (
          <span className="min-w-0 flex-1 truncate text-start">{city.name}</span>
        )}
      />
    </div>
  )
}

export { CitySearchSelect }

"use client"

import * as React from "react"
import { CheckIcon, ChevronsUpDownIcon, Loader2Icon } from "lucide-react"

import {
  InputGroup,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Popover,
  PopoverAnchor,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"

function usePopoverMenuWidth(
  open: boolean,
  rootRef: React.RefObject<HTMLDivElement | null>
) {
  const [menuWidth, setMenuWidth] = React.useState<number>()

  React.useLayoutEffect(() => {
    const el = rootRef.current
    if (!el) return
    const update = () => setMenuWidth(el.getBoundingClientRect().width)
    update()
    const ro = new ResizeObserver(update)
    ro.observe(el)
    return () => ro.disconnect()
  }, [open, rootRef])

  return menuWidth
}

export type PickerPopoverListProps<T> = {
  disabled?: boolean
  open: boolean
  onOpenChange: (open: boolean) => void
  listQuery: string
  onListQueryChange: (query: string) => void
  searchPlaceholder: string
  triggerLabel: React.ReactNode
  triggerAriaLabel: string
  emptyMessage: string
  loading?: boolean
  items: T[]
  getKey: (item: T) => string
  isSelected: (item: T) => boolean
  onPick: (item: T) => void
  renderItem: (item: T) => React.ReactNode
  className?: string
}

function PickerPopoverList<T>({
  disabled = false,
  open,
  onOpenChange,
  listQuery,
  onListQueryChange,
  searchPlaceholder,
  triggerLabel,
  triggerAriaLabel,
  emptyMessage,
  loading = false,
  items,
  getKey,
  isSelected,
  onPick,
  renderItem,
  className,
}: PickerPopoverListProps<T>) {
  const rootRef = React.useRef<HTMLDivElement>(null)
  const menuWidth = usePopoverMenuWidth(open, rootRef)

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (disabled) return
        onOpenChange(next)
        if (!next) onListQueryChange("")
      }}
      modal={false}
    >
      <PopoverAnchor asChild>
        <InputGroup
          ref={rootRef}
          data-disabled={disabled ? true : undefined}
          className={cn(
            "h-[46px] w-full rounded-md border-border/70",
            open ? "overflow-visible" : "overflow-hidden",
            disabled && "opacity-50",
            className
          )}
        >
          <PopoverTrigger asChild>
            <InputGroupButton
              type="button"
              disabled={disabled}
              aria-label={triggerAriaLabel}
              aria-expanded={open}
              className="h-full min-h-0 w-full cursor-pointer justify-between gap-2 rounded-md px-3 text-start font-normal disabled:cursor-not-allowed"
            >
              <span className="min-w-0 flex-1 truncate text-sm">
                {triggerLabel}
              </span>
              {loading ? (
                <Loader2Icon
                  className="size-4 shrink-0 animate-spin opacity-50"
                  aria-hidden
                />
              ) : (
                <ChevronsUpDownIcon
                  className="size-4 shrink-0 opacity-50"
                  aria-hidden
                />
              )}
            </InputGroupButton>
          </PopoverTrigger>
        </InputGroup>
      </PopoverAnchor>
      <PopoverContent
        align="start"
        className="w-auto p-0"
        style={menuWidth ? { width: menuWidth } : undefined}
        onOpenAutoFocus={(event) => {
          event.preventDefault()
          const panel = event.currentTarget
          if (!(panel instanceof HTMLElement)) return
          requestAnimationFrame(() => {
            panel
              .querySelector<HTMLInputElement>('input[type="search"]')
              ?.focus()
          })
        }}
        onCloseAutoFocus={(event) => event.preventDefault()}
      >
        <div className="border-b border-border/50 p-2">
          <InputGroup className="h-9 border-border/70">
            <InputGroupInput
              type="search"
              value={listQuery}
              onChange={(e) => onListQueryChange(e.target.value)}
              placeholder={searchPlaceholder}
              autoComplete="off"
              autoCorrect="off"
              spellCheck={false}
              className="h-9 text-sm"
            />
          </InputGroup>
        </div>
        <div className="max-h-72 overflow-y-auto py-0">
          {loading ? (
            <div className="flex items-center gap-2 px-3 py-6 text-sm text-muted-foreground">
              <Loader2Icon className="size-4 animate-spin" aria-hidden />
              Loading…
            </div>
          ) : items.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-muted-foreground">
              {emptyMessage}
            </p>
          ) : (
            items.map((item, index) => {
              const checked = isSelected(item)
              return (
                <button
                  key={getKey(item)}
                  type="button"
                  data-checked={checked ? true : undefined}
                  className={cn(
                    "flex w-full cursor-pointer items-center gap-2 px-3 py-2.5 text-sm outline-none",
                    "hover:bg-muted/50 focus-visible:bg-muted/50",
                    index < items.length - 1 && "border-b border-border/40"
                  )}
                  onClick={() => {
                    onPick(item)
                    onOpenChange(false)
                  }}
                >
                  {renderItem(item)}
                  {checked ? (
                    <CheckIcon
                      className="icon-dir ms-auto size-4 shrink-0 opacity-70"
                      aria-hidden
                    />
                  ) : null}
                </button>
              )
            })
          )}
        </div>
      </PopoverContent>
    </Popover>
  )
}

export { PickerPopoverList, usePopoverMenuWidth }

"use client"

import * as React from "react"
import type { City, Country, State } from "@sonojs/geo"

import { Label } from "@/components/ui/label"
import { cn } from "@/lib/utils"

import { CitySearchSelect } from "./city-search-select"
import { CountrySearchSelect } from "./country-search-select"
import { StateSearchSelect } from "./state-search-select"

export type CountryCitySelectProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange"
> & {
  country?: string | null
  defaultCountry?: string | null
  onCountryChange?: (iso2: string | null, country?: Country | null) => void
  /** Show state/province after country. */
  includeState?: boolean
  /** Show city after country (and after state when `includeState`). Default true. */
  includeCity?: boolean
  stateId?: number | null
  defaultStateId?: number | null
  onStateChange?: (stateId: number | null, state?: State | null) => void
  cityId?: number | null
  defaultCityId?: number | null
  onCityChange?: (cityId: number | null, city?: City | null) => void
  disabled?: boolean
  showFlags?: boolean
  countryLabel?: string
  stateLabel?: string
  cityLabel?: string
  countryPlaceholder?: string
  statePlaceholder?: string
  cityPlaceholder?: string
  geoDataBaseUrl?: string
  flagCdnBase?: string
  className?: string
}

function FieldBlock({
  label,
  htmlFor,
  children,
}: {
  label?: string
  htmlFor?: string
  children: React.ReactNode
}) {
  if (!label) return children
  return (
    <div className="grid w-full gap-2">
      <Label htmlFor={htmlFor}>{label}</Label>
      {children}
    </div>
  )
}

function CountryCitySelect({
  country: countryProp,
  defaultCountry = null,
  onCountryChange,
  includeState = false,
  includeCity = true,
  stateId: stateIdProp,
  defaultStateId = null,
  onStateChange,
  cityId: cityIdProp,
  defaultCityId = null,
  onCityChange,
  disabled = false,
  showFlags = true,
  countryLabel,
  stateLabel,
  cityLabel,
  countryPlaceholder = "Choose country",
  statePlaceholder = "Choose state / province",
  cityPlaceholder = "Choose city",
  geoDataBaseUrl,
  flagCdnBase,
  className,
  ...props
}: CountryCitySelectProps) {
  const reactId = React.useId()
  const countryFieldId = `${reactId}-country`
  const stateFieldId = `${reactId}-state`
  const cityFieldId = `${reactId}-city`

  const countryControlled = countryProp !== undefined
  const stateControlled = stateIdProp !== undefined
  const cityControlled = cityIdProp !== undefined
  const [uncontrolledCountry, setUncontrolledCountry] = React.useState<
    string | null
  >(defaultCountry)
  const [uncontrolledStateId, setUncontrolledStateId] = React.useState<
    number | null
  >(defaultStateId)
  const [uncontrolledCityId, setUncontrolledCityId] = React.useState<
    number | null
  >(defaultCityId)

  const countryIso = countryControlled ? countryProp : uncontrolledCountry
  const stateId = stateControlled ? stateIdProp : uncontrolledStateId
  const cityId = cityControlled ? cityIdProp : uncontrolledCityId

  const handleCountryChange = React.useCallback(
    (iso: string | null, country?: Country | null) => {
      if (!countryControlled) setUncontrolledCountry(iso)
      if (!stateControlled) setUncontrolledStateId(null)
      if (!cityControlled) setUncontrolledCityId(null)
      onCountryChange?.(iso, country ?? null)
      if (includeState) onStateChange?.(null, null)
      if (includeCity) onCityChange?.(null, null)
    },
    [
      cityControlled,
      countryControlled,
      includeCity,
      includeState,
      onCityChange,
      onCountryChange,
      onStateChange,
      stateControlled,
    ]
  )

  const handleStateChange = React.useCallback(
    (id: number | null, state?: State | null) => {
      if (!stateControlled) setUncontrolledStateId(id)
      if (!cityControlled) setUncontrolledCityId(null)
      onStateChange?.(id, state ?? null)
      if (includeCity) onCityChange?.(null, null)
    },
    [
      cityControlled,
      includeCity,
      onCityChange,
      onStateChange,
      stateControlled,
    ]
  )

  const handleCityChange = React.useCallback(
    (id: number | null, city?: City | null) => {
      if (!cityControlled) setUncontrolledCityId(id)
      onCityChange?.(id, city ?? null)
    },
    [cityControlled, onCityChange]
  )

  return (
    <div
      data-slot="country-city-select"
      className={cn("flex w-full flex-col gap-4", className)}
      {...props}
    >
      <FieldBlock label={countryLabel} htmlFor={countryFieldId}>
        <CountrySearchSelect
          id={countryFieldId}
          disabled={disabled}
          value={countryIso}
          placeholder={countryPlaceholder}
          geoDataBaseUrl={geoDataBaseUrl}
          flagCdnBase={flagCdnBase}
          showFlags={showFlags}
          onValueChange={handleCountryChange}
        />
      </FieldBlock>
      {includeState ? (
        <FieldBlock label={stateLabel} htmlFor={stateFieldId}>
          <StateSearchSelect
            id={stateFieldId}
            disabled={disabled}
            countryIso={countryIso}
            stateId={stateId}
            placeholder={statePlaceholder}
            geoDataBaseUrl={geoDataBaseUrl}
            onStateChange={handleStateChange}
          />
        </FieldBlock>
      ) : null}
      {includeCity ? (
        <FieldBlock label={cityLabel} htmlFor={cityFieldId}>
          <CitySearchSelect
            id={cityFieldId}
            disabled={disabled}
            countryIso={countryIso}
            stateId={includeState ? stateId : null}
            requireState={includeState}
            cityId={cityId}
            placeholder={cityPlaceholder}
            geoDataBaseUrl={geoDataBaseUrl}
            onCityChange={handleCityChange}
          />
        </FieldBlock>
      ) : null}
    </div>
  )
}

export { CountryCitySelect }
